with monthly_order as (select customer_id, trunc(created_at, 'MM') month_start, sum(amount) amount from orders where created_at >= date '2026-01-01' and status = 'PAID' group by customer_id, trunc(created_at, 'MM')), refund_order as (select customer_id, trunc(refund_time, 'MM') month_start, sum(refund_amount) amount from refunds where refund_time >= date '2026-01-01' and status = 'DONE' group by customer_id, trunc(refund_time, 'MM')) select customer_id, month_start, amount, 'ORDER' source_type from monthly_order where amount > 0 union all select customer_id, month_start, amount * -1 amount, 'REFUND' source_type from refund_order where amount > 0 union all select customer_id, add_months(month_start, 1) month_start, 0 amount, 'CARRY' source_type from monthly_order where amount is null order by customer_id, month_start, source_type;
